private OuterFaceCirculator selectOnOuterFace(Predicate<Node> predicate, Node start, Node stop, int dir) {
    OuterFaceCirculator circ = new OuterFaceCirculator(start);
    // If the start node is the stop node, return immediately
    if (circ.node().equals(stop)) {
        return circ;
    }
    // Traverse the outer face until we reach the stop node
    while (!circ.node().equals(stop)) {
        if (predicate.test(circ.node())) {
            return circ;
        }
        if (dir > 0) {
            circ.next();
        } else {
            circ.prev();
        }
    }
    // At this point circ is positioned at the stop node
    return circ;
}

