            ThreadSnapshot ts = ThreadSnapshot.parse(line); // assume a static parse method
            long time = ts.getTimestamp(); // assume a method that returns the snapshot timestamp
            for (ProfileAnalyzeTimeRange range : timeRanges) {
                if (time >= range.getStart() && time <= range.getEnd()) {
